html:
{%- set fam = doc.family_members or [] -%}
{%- set emp_addr = doc.current_address or doc.permanent_address or "" -%}
{%- macro val(v) -%}{{ v if v else "&nbsp;" }}{%- endmacro -%}
{%- macro fdate(d) -%}{{ frappe.utils.formatdate(d, "dd-MM-yyyy") if d else "" }}{%- endmacro -%}
{%- macro addr(r) -%}{{ r.address or (emp_addr if r.residing_with_employee else (r.place_of_residence or "")) }}{%- endmacro -%}
{%- macro age(d) -%}{{ ((frappe.utils.date_diff(frappe.utils.nowdate(), d) / 365.25) | int) if d else "" }}{%- endmacro -%}
{%- set company = frappe.db.get_value("Company", doc.company, ["pf_establishment_code", "esic_establishment_code"], as_dict=True) or {} -%}
{%- set co_links = frappe.get_all("Dynamic Link", filters={"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, pluck="parent", limit=1) -%}
{%- set ca = frappe.db.get_value("Address", co_links[0], ["address_line1", "address_line2", "city", "state", "pincode"], as_dict=True) if co_links else none -%}
{%- set co_address = ([ca.address_line1, ca.address_line2, ca.city, ca.state, ca.pincode] | select | join(", ")) if ca else "" -%}

<style>
	.sf { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; color: #000; line-height: 1.35; }
	.sf h3 { font-size: 13px; text-align: center; margin: 0 0 2px; }
	.sf .sub { text-align: center; font-size: 10px; margin-bottom: 6px; }
	.sf table { width: 100%; border-collapse: collapse; page-break-inside: avoid; }
	.sf td, .sf th { border: 1px solid #000; padding: 4px 6px; vertical-align: top; }
	.sf th { background: #eee; font-weight: bold; text-align: center; }
	.sf .n { width: 4%; text-align: center; }
	.sf .q { width: 38%; }
	.sf .part { font-weight: bold; text-align: center; margin: 8px 0 3px; }
	.sf .sign td { border: none; padding-top: 24px; }
	.sf .blank { display: inline-block; min-width: 150px; border-bottom: 1px solid #000; }
	.sf p { margin: 3px 0; }
	.sf .box { display: inline-block; width: 11px; height: 11px; border: 1px solid #000; text-align: center; font-size: 9px; line-height: 11px; vertical-align: middle; }
</style>
{%- set esic_nominee = (fam | selectattr("esic_nominee") | list | first) or none -%}
{%- set prev = (doc.external_work_history or []) | last -%}
<div class="sf">
	<h3>EMPLOYEES' STATE INSURANCE CORPORATION</h3>
	<div class="sub"><b>FORM 1 - DECLARATION FORM</b><br>(To be filled in by the employee after reading instructions overleaf. Two postcard-size photographs are to be attached with this form.)<br>(Regulation 11 and 12)</div>
	<table>
		<tr><th colspan="3" style="text-align:left">(A) INSURED PERSON'S PARTICULARS</th></tr>
		<tr><td class="n">1</td><td class="q">Insurance No.</td><td>{{ val(doc.esic_ip_number) }}</td></tr>
		<tr><td class="n">2</td><td class="q">Name (in block capitals)</td><td>{{ (doc.employee_name or "") | upper }}</td></tr>
		<tr><td class="n">3</td><td class="q">Father's / Husband's Name</td><td>{{ val(doc.father_or_husband_name) }}</td></tr>
		<tr><td class="n">4</td><td class="q">Date of Birth</td><td>{{ val(fdate(doc.date_of_birth)) }}</td></tr>
		<tr><td class="n">5</td><td class="q">Marital Status</td><td>{{ val(doc.marital_status) }}</td></tr>
		<tr><td class="n">6</td><td class="q">Sex</td><td>{{ val(doc.gender) }}</td></tr>
		<tr><td class="n">7</td><td class="q">Present Address<br>Mobile / Email</td><td>{{ val(doc.current_address) }}<br>{{ doc.cell_number or "" }}{% if doc.personal_email %} / {{ doc.personal_email }}{% endif %}</td></tr>
		<tr><td class="n">8</td><td class="q">Permanent Address</td><td>{{ val(doc.permanent_address) }}</td></tr>
		<tr><td class="n"></td><td class="q">Branch Office / Dispensary</td><td>{{ val(doc.get("esic_dispensary")) }}</td></tr>
		<tr><th colspan="3" style="text-align:left">(B) EMPLOYER'S PARTICULARS</th></tr>
		<tr><td class="n">9</td><td class="q">Employer's Code No.</td><td>{{ val(company.esic_establishment_code) }}</td></tr>
		<tr><td class="n">10</td><td class="q">Date of Appointment</td><td>{{ val(fdate(doc.date_of_joining)) }}</td></tr>
		<tr><td class="n">11</td><td class="q">Name &amp; Address of the Employer</td><td><b>{{ doc.company }}</b>{% if co_address %}<br>{{ co_address }}{% endif %}</td></tr>
		<tr><td class="n">12</td><td class="q">In case of any previous employment, please fill up the details as under:<br>(a) Previous Ins. No.<br>(b) Employer's Code No.<br>(c) Name &amp; address of the employer</td><td><br>(a) {{ doc.esic_ip_number if (prev and doc.esic_ip_number) else "" }}<br>(b) <br>(c) {{ prev.company_name if prev else "" }}{% if prev and prev.address %}, {{ prev.address }}{% endif %}</td></tr>
		<tr><th colspan="3" style="text-align:left">(C) DETAILS OF NOMINEE u/s 71 of ESI Act, 1948 / Rule 56(2) of ESI (Central) Rules, 1950 for payment of cash benefit in the event of death</th></tr>
		<tr><td class="n"></td><td class="q">Name</td><td>{{ val(esic_nominee.member_name if esic_nominee else "") }}</td></tr>
		<tr><td class="n"></td><td class="q">Relationship</td><td>{{ val(esic_nominee.relation if esic_nominee else "") }}</td></tr>
		<tr><td class="n"></td><td class="q">Address</td><td>{{ val(addr(esic_nominee) if esic_nominee else "") }}</td></tr>
	</table>
	<p>I hereby declare that the particulars given by me are correct to the best of my knowledge and belief. I undertake to intimate the Corporation any changes in the membership of my family within 15 days of such change.</p>
	<table class="sign"><tr><td>Counter signature by the Employer<br>Signature with seal<br>Dated: <span class="blank">&nbsp;</span></td><td style="text-align:right">Signature / T.I. of I.P.</td></tr></table>

	<div class="part">FAMILY PARTICULARS OF INSURED PERSON</div>
	<table>
		<tr><th style="width:6%">Sl. No.</th><th>Name</th><th style="width:16%">Date of Birth / Age as on date</th><th style="width:16%">Relationship with the Employee</th><th style="width:12%">Whether residing with him / her (Yes / No)</th><th style="width:22%">If 'No', state place of residence (Town, State)</th></tr>
		{% for r in fam %}
		<tr><td style="text-align:center">{{ loop.index }}</td><td>{{ r.member_name }}</td><td>{{ fdate(r.date_of_birth) }}{% if r.date_of_birth %} / {{ age(r.date_of_birth) }} yrs{% endif %}</td><td>{{ r.relation }}</td><td style="text-align:center">{{ "Yes" if r.residing_with_employee else "No" }}</td><td>{{ "" if r.residing_with_employee else (r.place_of_residence or "") }}</td></tr>
		{% endfor %}
		{% for i in range([4 - (fam | length), 0] | max) %}
		<tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td></tr>
		{% endfor %}
	</table>
	<p>I hereby declare that the particulars given by me are correct to the best of my knowledge and belief. I undertake to intimate the Corporation any changes in the membership of my family within 15 days of such change.</p>
	<table class="sign"><tr><td>Dated: <span class="blank">&nbsp;</span></td><td style="text-align:right">Signature / T.I. of I.P.</td></tr></table>
</div>
